import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import {
  demoPoseToScene,
  validateDemoSimResponse,
} from "@/components/mission-world/demo-sim/contract";
import { sceneToEnu } from "@/components/mission-world/enu";

/**
 * CHECKPOINT REGRESSION (Issue #33): kernel-observed poses from the exact
 * VQ-DEMO-SIM/1 fixture (generated by executing the REAL kernel, seed
 * 20261107) must map through the single ENU->scene conversion to exact
 * scene coordinates. Any double conversion, axis swap or rounding drift
 * breaks these numbers.
 */
const FIXTURE = validateDemoSimResponse(
  JSON.parse(
    readFileSync(
      path.resolve(__dirname, "fixtures/demo-sim-seed20261107.json"),
      "utf8",
    ),
  ),
);

describe("kernel pose -> scene coordinate regression (fixture, seed 20261107)", () => {
  it("fixture is the documented demo trace (10 steps, fault, 3 steps)", () => {
    expect(FIXTURE.snapshots).toHaveLength(13);
    expect(FIXTURE.seed).toBe(20261107);
    expect(FIXTURE.state.sequence).toBe(13);
    expect(FIXTURE.operations).toHaveLength(3);
    expect(FIXTURE.commandResults[0]?.ok).toBe(true);
  });

  it("drone at sequence 1 (pre-movement staging) maps exactly to its anchor scene point", () => {
    const drone = FIXTURE.snapshots[0]?.robots.find((r) => r.robotId === "drone-01");
    expect(drone).toBeDefined();
    expect(drone?.pose).toEqual({ x: -40, y: 80, z: 55 });
    expect(demoPoseToScene(drone!.pose)).toEqual([-40, 55, -80]);
  });

  it("rov faulted final pose maps exactly, staying underwater (scene y < 0)", () => {
    const rov = FIXTURE.snapshots[12]?.robots.find((r) => r.robotId === "rov-01");
    expect(rov).toBeDefined();
    const rovPose = rov!.pose;
    expect(rovPose.x).toBeCloseTo(65.985585, 6);
    expect(rovPose.y).toBeCloseTo(-13.99039, 6);
    expect(rovPose.z).toBeCloseTo(-2.799279, 6);
    const scene = demoPoseToScene(rovPose);
    expect(scene[0]).toBeCloseTo(65.985585, 6);
    expect(scene[1]).toBeCloseTo(-2.799279, 6);
    expect(scene[2]).toBeCloseTo(13.99039, 6);
    expect(scene[1]).toBeLessThan(0);
  });

  it("rover keeps deck-grounding: scene y equals route z 4.05 at every snapshot", () => {
    for (const snap of FIXTURE.snapshots) {
      const rover = snap.robots.find((r) => r.robotId === "rover-01");
      expect(rover).toBeDefined();
      const scene = demoPoseToScene(rover!.pose);
      expect(scene[1]).toBeCloseTo(4.05, 6);
    }
  });

  it("conversion is applied exactly once — inverse maps back to the ENU pose", () => {
    const rov = FIXTURE.snapshots[12]?.robots.find((r) => r.robotId === "rov-01");
    expect(rov).toBeDefined();
    const scene = demoPoseToScene(rov!.pose);
    const back = sceneToEnu(scene);
    expect(back[0]).toBeCloseTo(rov!.pose.x, 10);
    expect(back[1]).toBeCloseTo(rov!.pose.y, 10);
    expect(back[2]).toBeCloseTo(rov!.pose.z, 10);
  });

  it("the fault genuinely degrades measured optical quality; sonar is independent", () => {
    const before = FIXTURE.snapshots[9]?.robots.find((r) => r.robotId === "rov-01");
    const after = FIXTURE.snapshots[12]?.robots.find((r) => r.robotId === "rov-01");
    expect(before).toBeDefined();
    expect(after).toBeDefined();
    const opticalBefore = before!.sensors.find((s) => s.sensorId === "rov-01-optical")!.measured!.quality01;
    const opticalAfter = after!.sensors.find((s) => s.sensorId === "rov-01-optical")!.measured!;
    expect(opticalBefore).toBeGreaterThan(0.6);
    expect(opticalAfter.quality01).toBeLessThan(0.12);
    expect(opticalAfter.opticalVisibilityFactorApplied).toBe(0.12);
    const sonarAfter = after!.sensors.find((s) => s.sensorId === "rov-01-sonar")!.measured!;
    expect(sonarAfter.quality01).toBeGreaterThan(0.5); // unaffected by the optical fault
    expect(after!.activeOpticalFault?.severity).toBe("severe");
  });

  it("every snapshot pose converts to a finite scene position inside world bounds", () => {
    for (const snap of FIXTURE.snapshots) {
      for (const robot of snap.robots) {
        const scene = demoPoseToScene(robot.pose);
        for (const axis of scene) expect(Number.isFinite(axis)).toBe(true);
        expect(Math.abs(scene[0])).toBeLessThanOrEqual(300);
        expect(Math.abs(scene[2])).toBeLessThanOrEqual(200);
        expect(scene[1]).toBeGreaterThan(-16);
        expect(scene[1]).toBeLessThan(100);
      }
    }
  });
});
